app.get('/api/customers', async (req, res) => {
  try {
    const query = `
      SELECT
        customer_phone AS phone,
        MAX(customer_name) AS name,
        COUNT(id) AS total_orders,
        COUNT(CASE WHEN LOWER(TRIM(status)) = 'delivered' THEN 1 END) AS delivered_orders,
        COUNT(CASE WHEN LOWER(TRIM(status)) = 'cancelled' THEN 1 END) AS cancelled_orders,
        COALESCE(SUM(CASE WHEN LOWER(TRIM(status)) = 'delivered' THEN total_amount ELSE 0 END), 0) AS total_spent,
        MAX(created_at) AS last_order_date
      FROM orders
      WHERE customer_phone IS NOT NULL AND customer_phone != ''
      GROUP BY customer_phone
      ORDER BY total_orders DESC
    `;
    const result = await pool.query(query);
    res.json(result.rows);
  } catch (err) {
    res.status(500).json({
      error: err.message
    });
  }
});

