app.get('/api/finance/overview', async (req, res) => {
  try {
    const totalStats = await pool.query(`
      SELECT
        COALESCE(SUM(CASE WHEN LOWER(TRIM(status)) = 'delivered' THEN total_amount ELSE 0 END), 0) AS total_delivered_sales,
        COALESCE(SUM(CASE WHEN LOWER(TRIM(status)) = 'cancelled' THEN total_amount ELSE 0 END), 0) AS total_cancelled_amount,
        COUNT(CASE WHEN LOWER(TRIM(status)) = 'delivered' THEN 1 END) AS total_delivered_orders,
        COUNT(CASE WHEN LOWER(TRIM(status)) = 'cancelled' THEN 1 END) AS total_cancelled_orders
      FROM orders
    `);
    const codStats = await pool.query(`
      SELECT COALESCE(SUM(cash_in_hand), 0) AS total_rider_cod FROM riders
    `);
    const gross = Number(totalStats.rows[0].total_delivered_sales || 0);
    const commission = gross * 0.10;
    const netPayable = gross - commission;
    res.json({
      grossSales: gross,
      platformCommission: commission,
      netPayableToRestaurants: netPayable,
      cancelledAmount: Number(totalStats.rows[0].total_cancelled_amount || 0),
      deliveredCount: Number(totalStats.rows[0].total_delivered_orders || 0),
      cancelledCount: Number(totalStats.rows[0].total_cancelled_orders || 0),
      totalRiderCash: Number(codStats.rows[0].total_rider_cod || 0)
    });
  } catch (err) {
    res.status(500).json({
      error: err.message
    });
  }
});
